#include <map>

class stringx
{
public:
  int size() const;
  void to_upper();
};

class filespec
{
public:
  filespec(const stringx&);
  stringx name;
};

class vector3d
{
public:
  vector3d(float, float, float);
};

class po
{
public:
  po(const po&);
  void set_translate(const vector3d&);
};

extern po po_identity_matrix;

class entity {};
class entity_id
{
public:
  static entity_id make_unique_id();
};

typedef std::map<stringx, entity*> entfile_map;

class file_finder
{
public:
  void push_path_back(const stringx&);
  void pop_path_back();
};

class entity_maker
{
public:
  entity* create_entity_or_subclass(const stringx&, const entity_id&, const po&, const stringx&, unsigned int);
};

extern file_finder* g_file_finder;
extern entity_maker* g_entity_maker;
extern stringx empty_string;

class world_dynamics_system
{
  entfile_map entfiles;
public:
  const entfile_map& get_entfiles() const { return entfiles; }
  void remove_entity_from_world_processing(entity*);
  entity* create_preloaded_entity_or_subclass(const stringx&, const stringx&);
};

entity* world_dynamics_system::create_preloaded_entity_or_subclass( const stringx& entity_name,
                                                                   const stringx& entity_dir )
{
  entity* e;
  filespec spec( entity_name );
  spec.name.to_upper();
  entfile_map::const_iterator fi = get_entfiles().find( spec.name );

  po loc( po_identity_matrix );
  loc.set_translate( vector3d(-9000,-9000,-9000) );

  if ( fi == get_entfiles().end() )
  {
    if ( entity_dir.size() > 0 )
      g_file_finder->push_path_back( entity_dir );
    e = g_entity_maker->create_entity_or_subclass( entity_name,  entity_id::make_unique_id(), loc, empty_string, 0 );
    remove_entity_from_world_processing( e );
    if ( entity_dir.size() > 0 )
      g_file_finder->pop_path_back();
  }
  else
    e = (*fi).second;
  return e;
}
